<script setup lang="ts">
import {computed} from 'vue';import {useRoute} from 'vue-router';import type {TableColumnData} from '@arco-design/web-vue';import PageHeader from '../components/PageHeader.vue';import GiTable from '../components/GiTable.vue';import {resources} from '../api/resources';import {can} from '../state/session';import {api} from '../api/console';import {useResource} from '../composables/useResource';
const route=useRoute();const definition=computed(()=>resources[route.path]);const filters=computed(()=>({userId:typeof route.query.userId==='string'?route.query.userId:undefined}));
const columns=computed<TableColumnData[]>(()=>definition.value?.columns.map(c=>{const name=String(c.dataIndex??'');return name.endsWith('At')?{...c,render:({record})=>record[name]?new Date(Number(record[name])*1000).toLocaleString('zh-CN'):'—'}:c;})??[]);
const summary=useResource(api.backupSummary);if(route.path==='/backups'&&can('backup:status:view'))void summary.refresh();
</script>
<template><template v-if="definition&&can(definition.permission)"><page-header :title="definition.title" :description="definition.description"/><a-alert v-if="definition.notice" type="warning" class="notice">{{ definition.notice }}</a-alert><p v-if="summary.data.value" class="notice muted">{{ summary.data.value.storage.datasets }} 个数据集 · {{ summary.data.value.storage.snapshots??0 }} 份快照 · {{ (summary.data.value.storage.bytes/1048576).toFixed(2) }} MiB</p><gi-table :columns="columns" :load="definition.load" :filters="filters" :row-key="definition.rowKey"><template #actions="{record}"><router-link v-if="route.path==='/feedback'" :to="'/feedback/'+record.id">详情</router-link></template></gi-table></template><template v-else><page-header title="页面不可用" description="此页面不存在，或当前账号没有访问权限。"/><a-button @click="$router.push('/')">返回工作台</a-button></template></template>
